function reassemblePrep(texts, headerOverride) {
  const SESSION_RE = /===\s*SESSION\s*===[\s\S]*?(?=\n<!--SEGMENT|\n===|$)/;
  const UNRES_RE = /===\s*UNRESOLVED SPEAKERS\s*===([\s\S]*)$/;
  let header = (typeof headerOverride === 'string' && headerOverride.trim()) ? headerOverride.trim() : null;
  const bodies = [], unresolved = new Set();
  for (const raw of texts) {
    let t = raw;
    const u = t.match(UNRES_RE);
    if (u) {
      u[1].split('\n').map((l) => l.trim()).filter((l) => l.startsWith('-')).map((l) => l.replace(/\s+/g, ' ')).forEach((l) => unresolved.add(l));
      t = t.slice(0, u.index);
    }
    const segIdx = t.indexOf('<!--SEGMENT');
    if (segIdx > 0) {
      const head = t.slice(0, segIdx);
      const m = head.match(/===\s*SESSION\s*===[\s\S]*$/);
      if (m) {
        if (header === null) header = m[0].trim();
        t = t.slice(segIdx);
      }
    }
    if (t.trim()) bodies.push(t.trim());
  }
  let out = (header ? header + '\n\n' : '') + bodies.join('\n\n');
  if (unresolved.size) out += '\n\n=== UNRESOLVED SPEAKERS ===\n' + [...unresolved].join('\n');
  return out;
}


function extractMainThemes(text) {
  const m = text.match(/^main_themes:\s*(.*)$/m);
  return m ? m[1].trim() : '';
}

function formatDurationEstimate(transcriptText) {
  const matches = [...(transcriptText || '').matchAll(/\[(\d{2}):(\d{2}):(\d{2})\]/g)];
  if (!matches.length) return 'unknown';
  let maxSeconds = 0;
  for (const m of matches) {
    const s = (parseInt(m[1], 10) * 3600) + (parseInt(m[2], 10) * 60) + parseInt(m[3], 10);
    if (s > maxSeconds) maxSeconds = s;
  }
  const hours = Math.floor(maxSeconds / 3600);
  const minutes = Math.floor((maxSeconds % 3600) / 60);
  return `${hours}h ${minutes}m`;
}

function buildSessionHeader(date, durationEstimate, texts) {
  const seen = new Set();
  const themes = [];
  for (const t of texts) {
    const raw = extractMainThemes(t);
    if (!raw) continue;
    for (const part of raw.split(',')) {
      const theme = part.trim();
      if (theme && !seen.has(theme)) { seen.add(theme); themes.push(theme); }
    }
  }
  return `=== SESSION ===\ndate: ${date}\nduration_estimate: ${durationEstimate}\nmain_themes: ${themes.join('; ')}`;
}

